// JWT = base64url(header).base64url(payload).chữ_ký
const b64u = (o) => Buffer.from(JSON.stringify(o)).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const unb64u = (s) => JSON.parse(Buffer.from(s.replace(/-/g, "+").replace(/_/g, "/"), "base64").toString());

// CHỮ KÝ GIẢ chỉ để minh hoạ cấu trúc. Thực tế dùng HMAC-SHA256 (crypto.createHmac) hoặc RS256/EdDSA.
const sign = (data, secret) => b64u({ s: data.length + secret.length });

function createToken(payload, secret) {
  const head = b64u({ alg: "HS256", typ: "JWT" });
  const body = b64u(payload);
  return head + "." + body + "." + sign(head + "." + body, secret);
}

function verifyToken(token, secret, now) {
  const [h, p, sig] = token.split(".");
  if (sig !== sign(h + "." + p, secret)) return { ok: false, reason: "chữ ký sai" };
  const payload = unb64u(p);
  if (payload.exp && payload.exp <= now) return { ok: false, reason: "hết hạn" };
  return { ok: true, payload };
}

const t = createToken({ sub: "42", exp: 100 }, "s3cret");
console.log(verifyToken(t, "s3cret", 50).ok, verifyToken(t, "s3cret", 200).reason);

